//! On-disk session storage: `data_dir()/sessions/<id>/{info.json,messages.json}`.
//! Writes are atomic (tmp file + rename).

use hn_proto::{Message, SessionInfo};
use std::path::{Path, PathBuf};

pub fn sessions_dir() -> PathBuf {
    hn_proto::data_dir().join("sessions")
}

/// Session ids are generated by us; reject anything that could escape the sessions dir.
pub fn valid_id(id: &str) -> bool {
    !id.is_empty() && id.len() <= 128 && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
}

fn session_dir(id: &str) -> anyhow::Result<PathBuf> {
    anyhow::ensure!(valid_id(id), "invalid session id {id:?}");
    Ok(sessions_dir().join(id))
}

pub fn write_atomic(path: &Path, bytes: &[u8]) -> std::io::Result<()> {
    use std::io::Write;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    static SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let n = SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let tmp = path.with_extension(format!("tmp.{}.{n}", std::process::id()));
    {
        let mut f = std::fs::File::create(&tmp)?;
        f.write_all(bytes)?;
        f.sync_data()?;
    }
    std::fs::rename(&tmp, path)
}

/// Normalize live-only fields before writing.
fn stored_info(info: &SessionInfo) -> SessionInfo {
    let mut i = info.clone();
    i.open = false;
    i.attached = 0;
    i.status = Default::default();
    i
}

pub fn save_info(info: &SessionInfo) -> anyhow::Result<()> {
    let dir = session_dir(&info.id)?;
    let bytes = serde_json::to_vec_pretty(&stored_info(info))?;
    write_atomic(&dir.join("info.json"), &bytes)?;
    Ok(())
}

pub fn save_messages(id: &str, msgs: &[Message]) -> anyhow::Result<()> {
    let dir = session_dir(id)?;
    let bytes = serde_json::to_vec(msgs)?;
    write_atomic(&dir.join("messages.json"), &bytes)?;
    Ok(())
}

pub fn load_info(id: &str) -> anyhow::Result<SessionInfo> {
    let dir = session_dir(id)?;
    let text = std::fs::read_to_string(dir.join("info.json"))
        .map_err(|e| anyhow::anyhow!("session {id} not found ({e})"))?;
    Ok(serde_json::from_str(&text)?)
}

pub fn load(id: &str) -> anyhow::Result<(SessionInfo, Vec<Message>)> {
    let info = load_info(id)?;
    let dir = session_dir(id)?;
    let msgs = match std::fs::read(dir.join("messages.json")) {
        Ok(b) => serde_json::from_slice(&b)
            .map_err(|e| anyhow::anyhow!("session {id}: corrupt messages.json: {e}"))?,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(e) => return Err(e.into()),
    };
    Ok((info, msgs))
}

/// All persisted session infos (unsorted). Broken entries are skipped.
pub fn list_infos() -> Vec<SessionInfo> {
    let Ok(rd) = std::fs::read_dir(sessions_dir()) else { return Vec::new() };
    rd.filter_map(|e| e.ok())
        .filter_map(|e| std::fs::read_to_string(e.path().join("info.json")).ok())
        .filter_map(|t| serde_json::from_str::<SessionInfo>(&t).ok())
        .collect()
}

pub fn delete(id: &str) -> anyhow::Result<()> {
    let dir = session_dir(id)?;
    match std::fs::remove_dir_all(&dir) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(e) => Err(e.into()),
    }
}

/// Server-side session metadata that is not part of the protocol's SessionInfo.
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct SessionMeta {
    /// Name was set explicitly (create/rename): never auto-title.
    #[serde(default)]
    pub name_explicit: bool,
    /// An automatic title was already generated.
    #[serde(default)]
    pub titled: bool,
    /// must_report: a message to the parent was sent since the last parent request.
    #[serde(default)]
    pub reported: bool,
}

pub fn save_meta(id: &str, meta: &SessionMeta) -> anyhow::Result<()> {
    let dir = session_dir(id)?;
    write_atomic(&dir.join("meta.json"), &serde_json::to_vec_pretty(meta)?)?;
    Ok(())
}

pub fn load_full(id: &str) -> anyhow::Result<(SessionInfo, Vec<Message>, SessionMeta)> {
    let (info, msgs) = load(id)?;
    let dir = session_dir(id)?;
    let meta = std::fs::read_to_string(dir.join("meta.json"))
        .ok()
        .and_then(|t| serde_json::from_str(&t).ok())
        .unwrap_or(SessionMeta { name_explicit: false, titled: true, reported: false });
    Ok((info, msgs, meta))
}
